CREATE TABLE engine_tasks(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, title TEXT NOT NULL, context_json TEXT NOT NULL, markdown TEXT NOT NULL, source_ref TEXT NOT NULL, story_id TEXT, plan_id TEXT, status TEXT NOT NULL, strategy TEXT NOT NULL CHECK(strategy IN ('intelligent','deep')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL) STRICT;
CREATE INDEX engine_tasks_project ON engine_tasks(project_id,created_at);
CREATE TABLE engine_jobs(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES engine_tasks(id), project_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('plan','execute')), status TEXT NOT NULL, payload_json TEXT NOT NULL, result_json TEXT, owner TEXT, fence INTEGER NOT NULL DEFAULT 0, lease_until INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL) STRICT;
CREATE INDEX engine_jobs_queue ON engine_jobs(status,created_at);
CREATE TABLE engine_events(id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES engine_jobs(id), project_id TEXT NOT NULL, sequence INTEGER NOT NULL, version INTEGER NOT NULL, type TEXT NOT NULL, data_json TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(job_id,sequence)) STRICT;
CREATE TABLE engine_commands(project_id TEXT NOT NULL, command_key TEXT NOT NULL, content_hash TEXT NOT NULL, result_json TEXT NOT NULL, PRIMARY KEY(project_id,command_key)) STRICT;
CREATE TABLE engine_locks(resource TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES engine_jobs(id)) STRICT;
CREATE TABLE engine_operations(id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES engine_jobs(id), kind TEXT NOT NULL, state TEXT NOT NULL, reference_id TEXT, evidence_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_threads(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, title TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)), created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_messages(id TEXT PRIMARY KEY, thread_id TEXT NOT NULL REFERENCES engine_threads(id), role TEXT NOT NULL CHECK(role IN ('user','assistant','system')), text TEXT NOT NULL, task_id TEXT REFERENCES engine_tasks(id), created_at INTEGER NOT NULL) STRICT;
CREATE VIRTUAL TABLE engine_message_search USING fts5(message_id UNINDEXED,thread_id UNINDEXED,project_id UNINDEXED,text);
CREATE TABLE engine_requests(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES engine_tasks(id), kind TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL, answer TEXT, created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_permission_memory(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, scope_hash TEXT NOT NULL, operation_json TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('allow','deny')), actor TEXT NOT NULL, reason TEXT NOT NULL, policy_version INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER, created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_data_memory(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, scope_hash TEXT NOT NULL, reuse_key TEXT NOT NULL, guidance TEXT NOT NULL, references_json TEXT NOT NULL, actor TEXT NOT NULL, source_request_id TEXT NOT NULL REFERENCES engine_requests(id), created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_permission_events(id TEXT PRIMARY KEY, permission_id TEXT NOT NULL REFERENCES engine_permission_memory(id), actor TEXT NOT NULL, action TEXT NOT NULL, reason TEXT NOT NULL, created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_dependencies(task_id TEXT NOT NULL REFERENCES engine_tasks(id), prerequisite_id TEXT NOT NULL REFERENCES engine_tasks(id), PRIMARY KEY(task_id,prerequisite_id), CHECK(task_id<>prerequisite_id)) STRICT;
